package net.civeira.phylax.feature.observe.observedprobe.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedprobe.domain.ObservedProbe;
import net.civeira.phylax.feature.observe.observedprobe.domain.valueobject.LastLatencyMsVO;

class LastLatencyMsValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of last latency ms of observed probe")
  void test_last_latency_ms_value_holder_assign_plain_value() {
    Object holder = new Object();
    LastLatencyMsValueHolder<Object> value = new LastLatencyMsValueHolder<>(holder);
    Assertions.assertSame(holder, value.lastLatencyMs(1), "Setters must return the holder");
    Assertions.assertTrue(value.getLastLatencyMsValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(1, value.getLastLatencyMs().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.lastLatencyMsNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getLastLatencyMsValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getLastLatencyMs().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of last latency ms of observed probe")
  void test_last_latency_ms_value_holder_assign_value_object() {
    Object holder = new Object();
    LastLatencyMsValueHolder<Object> value = new LastLatencyMsValueHolder<>(holder);
    LastLatencyMsVO vo = LastLatencyMsVO.from(1);
    Assertions.assertFalse(value.getLastLatencyMsValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.lastLatencyMs(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getLastLatencyMsValue().orElseThrow());
    Assertions.assertSame(holder, value.lastLatencyMs(Optional.empty()));
    Assertions.assertFalse(value.getLastLatencyMsValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.lastLatencyMs(Optional.of(vo)));
    Assertions.assertSame(vo, value.getLastLatencyMsValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of last latency ms of observed probe against the original")
  void test_last_latency_ms_value_holder_read() {
    Object holder = new Object();
    LastLatencyMsValueHolder<Object> value = new LastLatencyMsValueHolder<>(holder);
    LastLatencyMsVO vo = LastLatencyMsVO.from(1);
    LastLatencyMsVO other = LastLatencyMsVO.from(1);
    ObservedProbe original = Mockito.mock(ObservedProbe.class);
    Mockito.when(original.getLastLatencyMsValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readLastLatencyMs(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readLastLatencyMs(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.lastLatencyMs(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readLastLatencyMs(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readLastLatencyMs(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of last latency ms of observed probe")
  void test_last_latency_ms_value_holder_unset() {
    Object holder = new Object();
    LastLatencyMsValueHolder<Object> value = new LastLatencyMsValueHolder<>(holder);
    LastLatencyMsVO vo = LastLatencyMsVO.from(1);
    value.lastLatencyMs(vo);
    Assertions.assertSame(holder, value.unsetLastLatencyMsIfMatches("lastLatencyMs_other"));
    Assertions.assertTrue(value.getLastLatencyMsValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetLastLatencyMsIfMatches("lastLatencyMs"));
    Assertions.assertFalse(value.getLastLatencyMsValue().isPresent(),
        "The field name must clear the value");
    value.lastLatencyMs(vo);
    Assertions.assertSame(holder, value.unsetLastLatencyMs());
    Assertions.assertFalse(value.getLastLatencyMsValue().isPresent(), "Unset must clear the value");
  }
}
